pages/search:
---
product_results:
    limit: {{theme_settings.searchpage_products_per_page}}
---
{{inject 'categoryTree' forms.search.category_options}}
{{inject 'searchProductsPerPage' theme_settings.searchpage_products_per_page}}
{{inject 'searchResultsCount' (lang 'search.results.count' count=result_count search_query=(sanitize forms.search.query))}}
{{#partial "head"}}
    <link rel="preload" href="{{cdn 'assets/dist/theme-bundle.chunk.search.js' resourceHint='preload' as='script'}}" as="script">
    <link rel="preload" href="{{cdn 'assets/dist/theme-bundle.chunk.jstree.js' resourceHint='preload' as='script'}}" as="script">
    {{#if pagination.product_results.previous}}
        <link rel="prev" href="{{pagination.product_results.previous}}">
    {{/if}}
    {{#if pagination.product_results.next}}
        <link rel="next" href="{{pagination.product_results.next}}">
    {{/if}}

    {{{ stylesheet '/assets/scss/vendor/jstree/style.css' }}}
{{/partial}}

{{#partial "page"}}
<section class="plp-page">
    {{#if result_count '>' 0}}
        <div class="plp-page-header is-open" id="page-sidebar-header">
            {{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}

            {{#if forms.search.query}}
                <div id="search-results-heading">
                    {{>components/search/heading}}
                </div>
            {{/if}}

            <div class="accordion accordion--navList accordion--suggestions">
                <div class="accordion-block">
                    <nav class="accordion-content is-open">
                        <span id="search-tabs-widget-description" class="aria-description--hidden">
                            {{lang 'search.tabs_accesibility_hint'}}
                        </span>
                        <ul role="tablist" class="eyeva__faceted-list" data-search-page-tabs>
                            <li role="presentation" class="eyeva__faceted-list-item">
                                <a aria-describedby="search-tabs-widget-description" role="tab" aria-controls="product-listing-container" id="search-results-product-count" class="eyeva__faceted-list-action" href="{{forms.search.product_url}}" data-product-results-toggle>
                                    {{>components/search/product-count}}
                                </a>
                            </li>
                            <li role="presentation" class="eyeva__faceted-list-item">
                                <a aria-describedby="search-tabs-widget-description" role="tab" aria-controls="search-results-content" id="search-results-content-count" class="eyeva__faceted-list-action" href="{{forms.search.content_url}}" data-content-results-toggle>
                                    {{>components/search/content-count}}
                                </a>
                            </li>
                            <!-- {{#unless product_results.faceted_search_enabled}}
                                <li class="eyeva__faceted-list-item">
                                    <a class="eyeva__faceted-list-action _view-all toggleLink" data-collapsible="advanced-search-content" href="#" aria-controls="advanced-search-content" aria-expanded="false">
                                        <span class="toggleLink-text toggleLink-text--on">
                                            {{lang 'forms.search.hide'}}
                                        </span>
                                        <span class="toggleLink-text toggleLink-text--off">
                                            {{lang 'forms.search.show'}}
                                        </span>
                                    </a>
                                </li>
                            {{/unless}} -->
                        </ul>
                    </nav>
                    <!-- {{#unless product_results.faceted_search_enabled}}
                        {{>components/search/advanced-search}}
                    {{/unless}} -->
                </div>

                {{#if forms.search.has_suggestions}}
                    {{#if forms.search.suggested_query}}
                        <div class="search-suggestion">
                            {{lang 'forms.search.did_you_mean'}} <strong>{{forms.search.suggested_query.query}}</strong>
                            <a href="{{forms.search.suggested_query.url}}" class="search-refine">{{lang 'forms.search.refine'}}</a>
                        </div>
                    {{/if}}

                    {{#if category_results.length}}
                        <div class="accordion-block">
                            <h5 class="accordion-heading">
                                <button type="button" class="accordion-navigation is-open" data-collapsible="#category-suggestion" aria-label="{{lang 'forms.search.categories'}}" aria-controls="category-suggestion" aria-expanded="true">
                                    <span class="_title">{{lang 'forms.search.categories'}}</span>
                                    <span class="icon"><svg><use href="#icon-chevron-down"></use></svg></span>
                                </button>
                            </h5>
                            <div id="category-suggestion" class="accordion-content is-open" aria-hidden="false">
                                <ul class="eyeva__faceted-list">
                                    {{#each category_results}}
                                        {{#each this}}
                                            <li class="eyeva__faceted-list-item">
                                                <a href="{{url}}" class="eyeva__faceted-list-action">{{name}}</a>
                                            </li>
                                        {{/each}}
                                    {{/each}}
                                </ul>
                            </div>
                        </div>
                    {{/if}}

                    {{#if brand_results.length}}
                        <div class="accordion-block">
                            <h5 class="accordion-heading">
                                <button type="button" class="accordion-navigation is-open" data-collapsible="#brand-suggestion" aria-label="{{lang 'forms.search.brand'}}" aria-controls="brand-suggestion" aria-expanded="true">
                                    <span class="_title">{{lang 'forms.search.brand'}}</span>
                                    <span class="icon"><svg><use href="#icon-chevron-down"></use></svg></span>
                                </button>
                            </h5>
                            <div id="brand-suggestion" class="accordion-content is-open" aria-hidden="false">
                                <ul class="eyeva__faceted-list">
                                    {{#each brand_results}}
                                        <li class="eyeva__faceted-list-item">
                                            <a href="{{url}}" class="eyeva__faceted-list-action">{{name}}</a>
                                        </li>
                                    {{/each}}
                                </ul>
                            </div>
                        </div>
                    {{/if}}
                {{/if}}
            </div>
        </div>

        {{#if product_results.pagination.total '>' 0}}
            {{> components/search/page-sidebar}}
        {{/if}}
    {{/if}}

    <main class="plp-page-main">
        {{#if result_count '===' 0}}
            {{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}
            {{>components/search/heading}}

            {{#if forms.search.has_suggestions}}
                <div class="search-suggestion">
                    {{lang 'forms.search.did_you_mean'}} <strong>{{forms.search.suggested_query.query}}</strong>
                    <a href="{{forms.search.suggested_query.url}}" class="search-refine">{{lang 'forms.search.refine'}}</a>
                </div>
            {{/if}}

            <div class="search-suggestion">
                <p>
                    {{lang 'forms.search.your_search_for'}}
                    "<strong>{{{sanitize forms.search.query}}}</strong>"
                    {{lang 'forms.search.no_match'}}
                </p>
            </div>
            <div class="search-suggestion">
                <h5 class="suggestion-title">{{lang 'forms.search.suggestions.title'}}</h5>
                <ul>
                    <li>{{lang 'forms.search.suggestions.line1'}}</li>
                    <li>{{lang 'forms.search.suggestions.line2'}}</li>
                    <li>{{lang 'forms.search.suggestions.line3'}}</li>
                </ul>
            </div>
        {{/if}}

        <div role="tabpanel" id="search-results-content" aria-labelledby="search-results-content-count" {{#if forms.search.section '!=' 'content'}}class="u-hidden"{{/if}}>
            {{> components/search/content-listing}}
        </div>

        <div role="tabpanel" id="product-listing-container" aria-labelledby="search-results-product-count" {{#if forms.search.section '!=' 'product'}}class="u-hidden"{{/if}}>
            {{> components/search/product-listing}}
        </div>
    </main>

    <div class="plp-page-region">
        {{{region name="search_below_content"}}}
        {{{region name="search_below_content--global"}}}
    </div>
</section>

{{/partial}}
{{> layout/base}}

components/search/content-listing:
{{#if content_results}}
    <div class="plp-page-main-header">
        <div class="_left">
            {{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}

            <button class="button button--plain eyeva__sidebar-toggle is-open" type="button" data-collapsible="page-sidebar-header" aria-expanded="true">
                <i class="icon" aria-hidden="true"><svg><use href="#icon-arrow-left-from-line"></use></svg></i>
                <span class="_title _on">{{lang 'search.faceted.hide-filters'}}</span>
                <span class="_title _off">{{lang 'search.faceted.show-filters'}}</span>
            </button>

            <span class="_products-count">
                {{lang 'search.results.content_count' count=pagination.content_results.total}}
            </span>
        </div>

        <span class="_plp-name">
            {{#if forms.search.search_error}}
                {{lang 'search.errorMessage' }}
            {{else}}
                {{{lang 'search.results.count' count=result_count search_query=(sanitize forms.search.query) }}}
            {{/if}}
        </span>

        {{#if product_results.products.length}}
            {{> components/search/content-sort-box sort=pagination.product_results.sort}}
        {{/if}}
    </div>

    <div class="search-content-results">
        {{#each content_results}}
            <div class="search-content-results-item">
                <p class="_title"><strong><a href="{{url}}">{{{title}}}</a></strong> ({{type}})</p>
                <p>{{{content}}}</p>
            </div>
        {{/each}}
    </div>

    {{> components/common/paginator pagination.content_results reload=true}}
{{/if}}

components/search/product-listing:
{{inject 'noCompareMessage' (lang 'compare.no_compare')}}

<div class="plp-page-main-header">

    <div class="_left">
        {{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}

        <button class="button button--plain eyeva__sidebar-toggle is-open" type="button" data-collapsible="page-sidebar-header" aria-expanded="true">
            <i class="icon" aria-hidden="true"><svg><use href="#icon-arrow-left-from-line"></use></svg></i>
            <span class="_title _on">{{lang 'search.faceted.hide-filters'}}</span>
            <span class="_title _off">{{lang 'search.faceted.show-filters'}}</span>
        </button>

        <span class="_products-count">
            {{lang 'search.results.product_count' count=pagination.product_results.total}}
        </span>
    </div>

    <span class="_plp-name">
        {{#if forms.search.search_error}}
            {{lang 'search.errorMessage' }}
        {{else}}
            {{{lang 'search.results.count' count=result_count search_query=(sanitize forms.search.query) }}}
        {{/if}}
    </span>

    {{#if product_results.products.length}}
        {{> components/products/filter sort=pagination.product_results.sort}}
    {{/if}}

    {{> components/faceted-search/header product_results}}
</div>



<div data-list-name="Search Results">
    {{#if theme_settings.product_list_display_mode '===' 'grid'}}
        {{> components/products/grid products=product_results.products show_compare=product_results.show_compare theme_settings=theme_settings event="list" }}
    {{else}}
        {{> components/products/list products=product_results.products show_compare=product_results.show_compare theme_settings=theme_settings event="list" }}
    {{/if}}
</div>

{{> components/common/paginator pagination.product_results}}

components/common/footer:
{{#if banners.bottom}}
<div class="banners" data-banner-location="bottom">
    {{#each banners.bottom_metadata}}
    <div class="banner" data-event-type="promotion" data-entity-id="{{this.id}}" data-name="{{this.banner-name}}"
        data-position="{{this.location}}" data-name="{{this.banner-name}}">
        <div data-event-type="promotion-click">
            {{{this.content}}}
        </div>
    </div>
    {{/each}}
</div>
{{/if}}
<footer class="footer" role="contentinfo">
    <h2 class="footer-title-sr-only">{{lang 'footer.title'}}</h2>
    <div class="footer-main">
        <div class="container">
            <section class="footer-info">
                <article class="footer-info-col" data-section-type="footer-categories">
                    <h3 class="footer-info-heading">{{lang 'footer.categories'}}</h3>
                    <ul class="footer-info-list">
                        {{#each categories}}
                        <li>
                            <a href="{{url}}">{{name}}</a>
                        </li>
                        {{/each}}
                    </ul>
                    {{{region name="footer_info_col_1--global"}}}
                </article>

                <article class="footer-info-col" data-section-type="footer-webPages">
                    <h3 class="footer-info-heading">{{lang 'footer.navigate'}}</h3>
                    <ul class="footer-info-list">
                        {{#each pages}}
                        <li>
                            <a href="{{url}}">{{name}}</a>
                        </li>
                        {{/each}}
                        {{#if settings.gift_certificates_enabled}}
                        <li>
                            <a href="{{urls.gift_certificate.purchase}}">{{lang 'common.gift_cert'}}</a>
                        </li>
                        {{/if}}
                        <li>
                            <a href="{{urls.sitemap}}">{{lang 'sitemap.page_title'}}</a>
                        </li>
                    </ul>
                    {{{region name="footer_info_col_2--global"}}}
                </article>

                <article class="footer-info-col" data-section-type="footer-brands">
                    {{#and theme_settings.shop_by_brand_show_footer shop_by_brand.length}}
                    <h3 class="footer-info-heading">{{lang 'footer.brands'}}</h3>
                    <ul class="footer-info-list">
                        {{#each shop_by_brand}}
                        <li>
                            <a href="{{url}}">{{name}}</a>
                        </li>
                        {{/each}}
                        <li><a href="{{urls.brands}}">{{lang 'common.view_all'}}</a></li>
                    </ul>
                    {{/and}}
                    {{{region name="footer_info_col_3--global"}}}
                </article>
                <article class="footer-info-col">
                    {{{region name="footer_info_col_4--global"}}}
                </article>
            </section>
            <section class="footer-contacts">
                {{#if settings.show_newsletter_box}}
                <section class="eyeva__newsletter">
                    <div class="container">
                        {{> components/common/subscription-form}}
                    </div>
                </section>
                {{/if}}
                <article class="footer-info-col" data-section-type="storeInfo">
                    <h3 class="footer-info-heading">{{lang 'footer.info'}}</h3>
                    {{#all settings.phone_number theme_settings.phone_text}}
                    <p>{{#replace '{phone}'
                        theme_settings.phone_text}}{{settings.phone_number}}{{else}}{{{theme_settings.phone_text}}}{{/replace}}
                    </p>
                    {{/all}}

                    {{{region name="footer_support--global"}}}

                    {{#if settings.phone_number}}
                    <p class="footer-contacts-callout"><a href="tel:{{settings.phone_number}}"><i class="icon"
                                aria-hidden="true"><svg>
                                    <use href="#icon-mobile-screen"></use>
                                </svg></i>{{settings.phone_number}}</a></p>
                    {{/if}}

                    {{#if theme_settings.social_icon_placement_bottom '!==' 'bottom_none'}}
                    {{> components/common/social-links}}
                    {{/if}}

                    {{#if settings.address}}
                    <address>{{settings.address}}</address>
                    {{/if}}
                </article>
                {{{region name="ssl_site_seal--global"}}}
            </section>
        </div>
    </div>

    {{> components/common/payment-icons}}

    <div class="footer-copyright">
        <div class="container">
            <p class="powered-by">
                {{#if theme_settings.show_copyright_footer}}
                &copy; {{moment format="YYYY"}} {{settings.store_name}}.
                {{/if}}
                {{#if theme_settings.show_powered_by}}
                {{lang 'footer.powered_by'}} <a
                    href="https://www.bigcommerce.com?utm_source=merchant&amp;utm_medium=poweredbyBC"
                    rel="nofollow">BigCommerce</a>.
                {{/if}}
            </p>

            {{{region name="footer_copyright_links--global"}}}
        </div>
    </div>
</footer>

components/products/grid:
{{#if hscroll}}<div class="productGrid-container">{{/if}}
    <ul class="productGrid {{#if hscroll}}productGrid--hscroll{{/if}}">
        {{#each products}}
        <li class="product">
            {{>components/products/card settings=../settings show_compare=../show_compare show_rating=../settings.show_product_rating theme_settings=../theme_settings customer=../customer event=../event position=(add @index 1)}}
        </li>
        {{/each}}
    </ul>
{{#if hscroll}}</div>{{/if}}

components/faceted-search/index:
{{> components/eyeva/faceted-search/init-image-color}}
<div id="facetedSearch" class="facetedSearch" role="region" aria-label="{{lang 'search.faceted.label'}}">
    {{#any facets visible=true}}
        <div id="facetedSearch-navList"
            class="facetedSearch-navList"
        >
            <div class="accordion accordion--navList">
                {{#each facets}}
                    {{#if visible}}
                        {{#inArray ../theme_settings.facet_img_arr (lowercase facet)}}
                            {{#if (merge this isFacetImg=true)}}{{/if}}
                        {{/inArray}}
                        {{#inArray ../theme_settings.facet_color_arr (lowercase facet)}}
                            {{#if (merge this isFacetColor=true)}}{{/if}}
                        {{/inArray}}
                        {{{dynamicComponent 'components/faceted-search/facets'}}}
                    {{/if}}
                {{/each}}
            </div>

            <div class="blocker" style="display: none;"></div>
        </div>
    {{/any}}
</div>

components/eyeva/header/navuser-currency:
{{#or customer (unless settings.hide_price_from_guests)}}
    {{#if currency_selector.currencies.length '>' 1}}
        <button class="navUser-action _currency" type="button"
            data-collapsible="navUser-currency"
            aria-controls="navUser-currency"
            aria-expanded="false"
            aria-label="{{currency_selector.active_currency_code}}"
            data-menu-gap-cover
        >
            <span class="navUser-label-alt">{{currency_selector.active_currency_code}}</span>
            <i class="icon" aria-hidden="true"><svg><use href="#icon-chevron-down" /></svg></i>
        </button>
        <div class="navUser-subMenu" id="navUser-currency" aria-hidden="true" data-menu-dropdown {{#if theme_settings.logo-position '==' 'center'}}data-ignore-header-position{{/if}}>
            <ul class="navUser-childList">
                {{#each currency_selector.currencies}}
                    <li class="navUser-childList-item">
                        <a class="navUser-childList-action" href="{{{switch_url}}}"
                            data-currency-code="{{{code}}}"
                            {{#if cart_currency_switch_url.length '>' 0 }}
                                data-cart-currency-switch-url="{{{cart_currency_switch_url}}}"
                            {{/if}}
                            data-warning="{{lang 'common.currency_switch_promotion'}}"
                        >
                            {{#if is_active}}
                                <strong>{{code}} - {{name}}</strong>
                            {{else}}
                                {{code}} - {{name}}
                            {{/if}}
                        </a>
                    </li>
                {{/each}}
            </ul>
        </div>
    {{/if}}
{{/or}}

components/products/card-actions:
{{#or customer (unless settings.hide_price_from_guests)}}
    {{#if show_cart_action}}
        {{~inject 'show_cart_action' true}}
        {{#if has_options}}
            {{> components/products/card-qty}}
            {{#if theme_settings.show_product_quick_view}}
                <button type="button" class="card-figcaption-button quickview _choose-options" data-event-type="product-click" data-product-id="{{id}}">
                    <span class="icon"><svg aria-hidden="true"><use href="#icon-cart-shopping-fast"></use></svg></span>
                    <span class="_label">{{lang 'products.choose_options'}}</span>
                </button>
            {{else}}
                <a href="{{url}}" data-event-type="product-click" class="card-figcaption-button _choose-options" data-product-id="{{id}}">
                    <span class="icon"><svg aria-hidden="true"><use href="#icon-cart-shopping-fast"></use></svg></span>
                    <span class="_label">{{lang 'products.choose_options'}}</span>
                </a>
            {{/if}}
        {{/if}}
        {{#if pre_order}}
            {{> components/products/card-qty}}
            {{#if pre_order_add_to_cart_url}}
                <a href="{{pre_order_add_to_cart_url}}" data-event-type="product-click" class="card-figcaption-button _preorder" data-papathemes-cart-item-add>
                    <span class="icon"><svg aria-hidden="true"><use href="#icon-cart-shopping-fast"></use></svg></span>
                    <span class="_label">{{lang 'products.pre_order'}}</span>
                </a>
            {{else if theme_settings.show_product_quick_view}}
                <button type="button" class="card-figcaption-button quickview _preorder" data-event-type="product-click" data-product-id="{{id}}">
                    <span class="icon"><svg aria-hidden="true"><use href="#icon-cart-shopping-fast"></use></svg></span>
                    <span class="_label">{{lang 'products.pre_order'}}</span>
                </button>
            {{/if}}
        {{/if}}
        {{#if add_to_cart_url}}
            {{> components/products/card-qty}}
            <a href="{{add_to_cart_url}}" data-event-type="product-click" data-button-type="add-cart" class="card-figcaption-button _add-to-cart" data-papathemes-cart-item-add>
                <span class="icon"><svg aria-hidden="true"><use href="#icon-cart-shopping-fast"></use></svg></span>
                <span class="_label">{{lang 'products.add_to_cart'}}</span>
            </a>
            <span class="product-status-message aria-description--hidden">{{lang 'category.add_cart_announcement'}}</span>
        {{/if}}
        {{#if out_of_stock_message }}
            <a href="{{url}}" data-event-type="product-click" class="card-figcaption-button _outstock" data-product-id="{{id}}">
                <span class="_label">{{out_of_stock_message}}</span>
            </a>
        {{/if}}
    {{/if}}
{{/or}}
{{#unless hide_product_quick_view}}
    {{#if theme_settings.show_product_quick_view}}
        <button type="button" class="card-figcaption-button quickview" data-event-type="product-click" data-product-id="{{id}}">
            <span class="icon"><svg aria-hidden="true"><use href="#icon-magnifying-glass"></use></svg></span>
            <span class="is-srOnly">{{lang 'products.quick_view'}}</span>
        </button>
    {{/if}}
{{/unless}}
{{#if show_compare}}
    <button type="button" class="card-figcaption-button compare"
        data-compare-id="{{id}}"
        data-compare-image="{{getImage image 'productthumb_size' (cdn theme_settings.default_image_product)}}"
        data-compare-title="{{name}}" data-compare-url="{{url}}"
    >
        <span class="icon"><svg aria-hidden="true"><use href="#icon-chart-line"></use></svg></span>
        <span class="is-srOnly">{{lang 'products.quick_view'}}</span>
    </button>
{{/if}}

components/products/price:
{{!-- There are 2 code paths for generating the PDP pricing HTML determined by the following #and condition.
If a 'price_range' exists then we generate all HTML in price-range.html, otherwise it is defined here. Both code
paths generate the same HTML structure with some differences in whether that element is displayed by default (css styling).

If you are making a change here or in price-range.html, you probably want to make that change in both files. --}}

{{#and price.price_range (if theme_settings.price_ranges '==' true)}}
    {{> components/products/price-range price=price}}
{{else}}
    <div class="price-section price-section--withTax price--withTax" {{#unless price.with_tax}}style="display: none;"{{/unless}}>
        {{#if price.price_range}}
            <span class="price-starting-label">{{theme_settings.pdp-starting-price-label}}</span>
        {{/if}}
        <span class="price-label" {{#or price.non_sale_price_with_tax price.price_range}}style="display: none;"{{/or}}>
            {{theme_settings.pdp-price-label}}
        </span>
        <span class="price-now-label" {{#or (unless price.non_sale_price_with_tax) price.price_range}}style="display: none;"{{/or}}>
            {{> components/products/price-label
                label_value=theme_settings.pdp-sale-price-label
                fallback=(lang "page_builder.pdp-sale-price-label")
            }}
        </span>
        <span data-product-price-with-tax class="price price--main">{{price.with_tax.formatted}}</span>
        {{#if price.without_tax}}
            <abbr title="{{lang 'products.including_tax'}}">{{lang 'products.price_with_tax' tax_label=price.tax_label}}</abbr>
        {{/if}}
    </div>
    <div class="price-section price-section--withTax non-sale-price--withTax" {{#unless price.non_sale_price_with_tax}}style="display: none;"{{/unless}}>
        <span>
            {{> components/products/price-label
                label_value=theme_settings.pdp-non-sale-price-label
                fallback=(lang "page_builder.pdp-non-sale-price-label")
            }}
        </span>
        <span data-product-non-sale-price-with-tax class="price price--non-sale">
            {{price.non_sale_price_with_tax.formatted}}
        </span>
    </div>
    <div class="price-section price-section--withTax rrp-price--withTax" {{#unless price.rrp_with_tax}}style="display: none;"{{/unless}}>
        <span>
            {{> components/products/price-label
                label_value=theme_settings.pdp-retail-price-label
